function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

  background(0, 50);

  let emitterX = width / 2 + cos(emitterAngle) * random(250);
  let emitterY = height / 2 + sin(emitterAngle) * random(250);
  emitterAngle += 0.04;

  // 新しいパーティクルを追加
  particles.push(new Particle(emitterX, emitterY));

  // 各パーティクルを描画
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].update();
    particles[i].show();

    // 消えるタイミングで配列から削除
    if (particles[i].isFinished()) {
      particles.splice(i, 1);
    }
  }

  pop();
}

class Particle {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(1, 3));
    this.lifespan = 255;
    this.char = characters[currentCharIndex]; // 現在の文字を取得
    this.size = random(20, 60);
    this.rotation = random(TWO_PI);
    this.rotationSpeed = random(-0.05, 0.05);

    // 次の文字インデックスに進む（ループ）
    currentCharIndex = (currentCharIndex + 1) % characters.length;

    // 文字が描画されるときに発音
    this.speak();
  }

  // 日本語の音読み発音
  speak() {
    let pronunciation = kanjiToOnyomi[this.char] || this.char; // 音読みがない場合はそのまま
    let utterance = new SpeechSynthesisUtterance(pronunciation); // 発音する文字を指定
    utterance.lang = "ja-JP"; // 日本語に設定
    utterance.rate = 1; // 読み上げ速度
    utterance.pitch = 1; // 声の高さ
    speechSynth.speak(utterance); // 発音
  }

  update() {
    this.pos.add(this.vel);
    this.lifespan -= 2;
    this.rotation += this.rotationSpeed;
  }

  show() {
    push();
    translate(this.pos.x, this.pos.y);
    rotate(this.rotation);

    blendMode(ADD);

    for (let i = 10; i > 0; i--) {
      let alpha = map(i, 0, 10, 0, this.lifespan / 2);
      let glowColor = color(random(neonPalette));
      glowColor.setAlpha(alpha / 50);
      noStroke();
      fill(glowColor);
      ellipse(0, 0, this.size + i * 8);
    }

    let neonColor = random(neonPalette);
    neonColor.setAlpha(this.lifespan);
    fill(neonColor);
    textSize(this.size);
    textAlign(CENTER, CENTER);
    text(this.char, 0, 0);

    pop();
  }

  isFinished() {
    return this.lifespan < 0;
  }
}


